const FOOD_REFERENCES=[
 ['WHO Healthy diet','https://www.who.int/news-room/fact-sheets/detail/healthy-diet'],
 ['FAOSTAT food and agriculture statistics','https://www.fao.org/faostat/'],
 ['USDA FoodData Central','https://fdc.nal.usda.gov/'],
 ['Australian Food Composition Database','https://www.foodstandards.gov.au/science-data/food-nutrient-databases/afcd/data-files'],
 ['WHO traditional medicine — evidence and safety','https://www.who.int/news-room/questions-and-answers/item/traditional-medicine']
];
function foodCountry(name){const n=String(name||'').trim().toLowerCase();return FOOD_COUNTRIES.find(c=>c.country.toLowerCase()===n)||null;}
function foodNutrition(food,grams){const f=FOOD_NUTRIENTS.find(x=>x.food===food);if(!f)return null;const g=Number(grams);if(!Number.isFinite(g)||g<=0||g>3000)return null;return {name:f.food,grams:g,kcal:Math.round(f.kcal_100g*g/100),protein:Math.round(f.protein_g_100g*g/10)/10,carbs:Math.round(f.carbs_g_100g*g/10)/10,fiber:Math.round(f.fiber_g_100g*g/10)/10};}
function foodSafe(s){return safe(String(s??''));}
function foodLibrary(){const selected=window.foodSelectedCountry||profile().healthy?.country||'India';const c=foodCountry(selected)||foodCountry('India');const gram=Number(window.foodSelectedGram||100), item=FOOD_NUTRIENTS.find(f=>f.food===window.foodSelectedItem)||FOOD_NUTRIENTS[0];const calc=foodNutrition(item.food,gram);const list=FOOD_COUNTRIES.map(x=>`<option value="${foodSafe(x.country)}" ${c.country===x.country?'selected':''}>${foodSafe(x.country)}</option>`).join('');const foods=FOOD_NUTRIENTS.map(x=>`<option value="${foodSafe(x.food)}" ${item.food===x.food?'selected':''}>${foodSafe(x.food)}</option>`).join('');return head('195-country food library','Regional traditional foods, ingredients and nutrition — with transparent evidence labels.')+`<div class="callout"><b>Worldwide coverage:</b> 195 country selectors; ${FOOD_COUNTRIES.filter(x=>x.specificity.startsWith('country')).length} curated country examples, other countries use <b>clearly marked regional starter examples</b>. These are not verified local agriculture, traditional treatment, or representative of every community. Country, ethnicity and medical risk are not interchangeable.</div><div class="grid equal"><section class="card"><h2>1 · Explore country food culture</h2><label class="field"><span>Country (195 available)</span><select id="foodCountrySelect">${list}</select></label><div id="foodCountryDetail">${foodCountryDetail(c)}</div><h3>Food as tradition, not medicine</h3><p>Historical uses of foods and herbs can be interesting cultural information, but do not demonstrate prevention or treatment of disease. Herbs can interact with medicines; do not replace diabetes, blood-pressure or other prescribed treatment.</p><h3>Natural cooking ideas</h3><p>Steaming, simmering, roasting and grilling can preserve familiar flavours while moderating added salt and excess oil. Food safety, washing produce, safe cooking temperatures and allergen controls still matter.</p><h3>Evidence and data sources</h3>${FOOD_REFERENCES.map(x=>`<p><a href="${foodSafe(x[1])}" target="_blank" rel="noopener noreferrer">${foodSafe(x[0])} ↗</a></p>`).join('')}</section><section class="card"><h2>2 · Ingredient nutrition estimator</h2><div class="callout warning">Indicative rounded values for common ingredients only. Not yet synchronised to a live USDA/FAO dataset. Values depend on cultivar, preparation and moisture; never treat a meal estimate as a lab measurement.</div><label class="field"><span>Ingredient</span><select id="foodIngredient">${foods}</select></label><label class="field"><span>Weight in grams</span><input id="foodGrams" type="number" min="1" max="3000" step="1" value="${foodSafe(gram)}" /></label><div id="foodNutritionDetail">${foodNutritionDetail(calc,item)}</div><h3>Benefits: food-group level, not therapeutic claims</h3><ul><li>Vegetables and fruits provide dietary fibre, vitamins and plant compounds.</li><li>Beans and lentils provide protein and fibre, and can support a balanced dietary pattern.</li><li>Whole grains offer fibre and can be part of a heart-healthy eating pattern.</li><li>Herbs and spices add flavour without requiring heavy added salt.</li><li>No single food or home remedy guarantees longer life or cures a chronic condition.</li></ul><p><b>Source note:</b> USDA FoodData Central is the target authoritative nutrient source for future verified food IDs; FAOSTAT is for country agricultural/food-supply evidence, not individual food calories.</p></section></div>`;}
const FOOD_VISUAL_EMOJI=[['papaya','🍈'],['mango','🥭'],['banana','🍌'],['apple','🍎'],['orange','🍊'],['guava','🍐'],['grape','🍇'],['avocado','🥑'],['carrot','🥕'],['tomato','🍅'],['maize','🌽'],['corn','🌽'],['rice','🍚'],['beans','🫘'],['lentil','🫘'],['chickpea','🫘'],['potato','🥔'],['cassava','🥔'],['pumpkin','🎃'],['fish','🐟'],['chicken','🍗'],['leaf','🥬'],['spinach','🥬'],['kale','🥬'],['salad','🥗'],['bread','🍞'],['egg','🥚'],['olive','🫒'],['noodle','🍜'],['wheat','🌾'],['barley','🌾'],['oats','🌾']];
function foodVisualEmoji(s){const t=String(s||'').toLowerCase();return FOOD_VISUAL_EMOJI.find(([k])=>t.includes(k))?.[1]||'🥣'}
const FOOD_VISUAL_PHOTOS=[['papaya','papaya'],['mango','mango'],['banana','banana'],['apple','apple'],['orange','orange'],['avocado','avocado'],['carrot','carrot'],['tomato','tomato'],['corn','maize'],['maize','maize'],['beans','beans'],['bean','beans'],['rice','rice'],['spinach','spinach']];
function foodPhoto(s){const t=String(s||'').toLowerCase();const k=FOOD_VISUAL_PHOTOS.find(([token])=>t.includes(token));return k?'assets/food_'+k[1]+'.jpg':null;}
function foodGallery(c){const items=[...new Set((c.staples+','+c.produce).split(',').map(x=>x.trim()).filter(Boolean))].slice(0,12);return `<h3>Visual food gallery · illustrative icons</h3><div class="food-picture-grid">${items.map(x=>`<div class="food-picture"><div class="art" role="img" aria-label="Illustrative image for ${foodSafe(x)}">${foodPhoto(x)?`<img loading="lazy" src="${foodPhoto(x)}" alt="Generated illustrative photo of ${foodSafe(x)}">`:foodVisualEmoji(x)}</div><div class="label">${foodSafe(x)}<span class="sub">Cultural example · not crop verification</span></div></div>`).join('')}</div><p class="filehint">Illustrative generated photographs are available for 12 common ingredients; other entries use pictograms. Verified country-specific crop-level photography and source records are not available for every country. Nutrition estimates remain limited to the existing 27 generic ingredient records.</p>`}
function foodCountryDetail(c){return `<div class="entry-row"><div class="entry-info"><strong>${foodSafe(c.country)} · ${foodSafe(c.region)}</strong><small>${foodSafe(c.specificity)}</small></div></div>${foodGallery(c)}<h3>Illustrative staples and plant foods</h3><p><b>Staple examples:</b> ${foodSafe(c.staples)}</p><p><b>Fruit & vegetables:</b> ${foodSafe(c.produce)}</p><p><b>Cooking traditions:</b> ${foodSafe(c.methods)}</p><div class="callout warning"><b>Local cultivation is unverified.</b> Regional food examples may be imported, seasonal, or uncommon in parts of this country. Confirm availability and growing locations using FAOSTAT country crop data. Local and Indigenous knowledge requires specific, attributable sources.</div><p><b>Healthy adjustment:</b> Add vegetables and adequate protein; consider wholegrains/legumes where suitable; adjust to preferences, food allergies and medical needs.</p>`;}
function foodNutritionDetail(v,f){return v?`<div class="metrics"><div class="metric"><span>Calories · estimate</span><b>${v.kcal} kcal</b></div><div class="metric"><span>Protein</span><b>${v.protein} g</b></div><div class="metric"><span>Carbohydrate</span><b>${v.carbs} g</b></div><div class="metric"><span>Fibre</span><b>${v.fiber} g</b></div></div><p><b>Food note:</b> ${foodSafe(f.nutrient_note)}</p>`:'<p>Enter a weight from 1 to 3,000 g.</p>'; }
function foodRefresh(){const n=document.getElementById('foodCountrySelect');if(n){window.foodSelectedCountry=n.value;const c=foodCountry(n.value);document.getElementById('foodCountryDetail').innerHTML=foodCountryDetail(c);}}
function foodRefreshNutrients(){const el=document.getElementById('foodIngredient'),grams=document.getElementById('foodGrams');if(!el||!grams)return;window.foodSelectedItem=el.value;window.foodSelectedGram=grams.value;document.getElementById('foodNutritionDetail').innerHTML=foodNutritionDetail(foodNutrition(el.value,grams.value),FOOD_NUTRIENTS.find(x=>x.food===el.value));}
if(typeof document!=='undefined'){document.addEventListener('change',e=>{if(e.target?.id==='foodCountrySelect')foodRefresh();if(['foodIngredient','foodGrams'].includes(e.target?.id))foodRefreshNutrients();});document.addEventListener('input',e=>{if(e.target?.id==='foodGrams')foodRefreshNutrients();});}
